/* PSG DNA — Parc des Princes navy, hechter red stripe */
.theme-psg {
  --bg: oklch(0.216 0.047 256.0);
  --surface: color-mix(in oklab, oklch(0.216 0.047 256.0) 92%, white);
  --surface-2: color-mix(in oklab, oklch(0.216 0.047 256.0) 84%, white);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.711 0.018 250.9);
  --accent: oklch(0.367 0.099 248.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.575 0.213 29.6);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Saira", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-psg h1,
.theme-psg h2,
.theme-psg h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-psg { --font-ui: var(--font-display); }
.theme-psg h1, .theme-psg h2 { text-transform: uppercase; font-weight: 700; }
.theme-psg h1::after { content: ""; display: block; height: 4px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }
.theme-psg button { text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
